import gurobipy as gp
from gurobipy import GRB
shelves = []
capacity = {}
for rec in LEGACY_RECORDS:
    if rec['source'] == 'capacity.csv':
        shelf_id = rec['values']['resource_id']
        shelves.append(shelf_id)
        capacity[shelf_id] = int(rec['values']['resource_capacity'])
products = []
value = {}
requirement = {}
for rec in LEGACY_RECORDS:
    if rec['source'] == 'products.csv':
        prod_id = rec['values']['item_name']
        products.append(prod_id)
        value[prod_id] = int(rec['values']['item_value'])
        requirement[prod_id] = int(rec['values']['resource_requirement'])
if len(set(shelves)) != len(shelves):
    raise ValueError('Duplicate shelf ids found')
if len(set(products)) != len(products):
    raise ValueError('Duplicate product ids found')
if set(capacity.keys()) != set(shelves):
    raise ValueError('Missing shelf capacity data')
if set(value.keys()) != set(products) or set(requirement.keys()) != set(products):
    raise ValueError('Missing product value or requirement data')
m = gp.Model('BigMart_Shelf_Allocation')
x = m.addVars(shelves, products, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((value[j] * x[i, j] for i in shelves for j in products)), GRB.MAXIMIZE)
m.addConstrs((gp.quicksum((requirement[j] * x[i, j] for j in products)) <= capacity[i] for i in shelves), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')